frappe.ready(() => {
    if (window.location.pathname.includes('/job')) {
        // Hide the header on ERPNext pages
        $('nav').css('display', 'none');
        // Hide the footer on ERPNext pages
        $('footer').css('display', 'none');
        // Wait for the DOM to fully load
        const hideBreadcrumbs = () => {
            const breadcrumbs = document.querySelector('.breadcrumb-container');
            if (breadcrumbs) {
                breadcrumbs.style.display = 'none';
            }
        };
        // Try to hide immediately
        hideBreadcrumbs();
        // Also listen for page change events (like in single-page routing)
        $(document).on('page-change', hideBreadcrumbs);
    }
});

